def leftPartLength(nums):
    left_max = nums[0]
    seen_max = nums[0]
    length = 1
    for i in range(1, len(nums)):
        x = nums[i]
        if x < left_max:
            length = i + 1
            left_max = seen_max
        elif x > seen_max:
            seen_max = x
    return length
